FUNCTION_BLOCK dw
VAR_INPUT
    i: INT;
END_VAR_INPUT

VAR_OUTPUT
    o: INT;
END_VAR_OUTPUT

VAR
    ss: INT := 0; // Initialize ss to 0
END_VAR

// Increment ss each time the function block is executed
ss := ss + 1;

// Determine output based on input value
CASE i OF
    1: 
        o := 1; // If input is 1, set output to 1
    ELSE
        o := ss; // Otherwise, set output to the current value of ss
END_CASE;

END_FUNCTION_BLOCK

PROGRAM MAIN
VAR
    fb_dw: dw; // Instance of the function block
    input_value: INT := 3; // Input value to be passed to the function block
    output_value: INT; // Variable to hold the output from the function block
END_VAR

// Call the function block with the input value
fb_dw(i := input_value);

// Retrieve the output from the function block
output_value := fb_dw.o;

END_PROGRAM
